solution.Text.java:
import java.util.*;

class Text {
    static List<String> topWords(String text, int n) {
        Map<String, Integer> counts = new HashMap<>();
        for (String w : text.toLowerCase().split("[^\\p{L}]+")) {
            if (!w.isEmpty()) counts.merge(w, 1, Integer::sum);
        }
        Set<String> alphabetical = new TreeSet<>(counts.keySet());
        int most = 0;
        for (int c : counts.values()) most = Math.max(most, c);
        List<String> result = new ArrayList<>();
        for (int c = most; c >= 1; c--) {                 // the highest count first
            for (String w : alphabetical) {
                if (counts.get(w) == c && result.size() < n) result.add(w);
            }
        }
        return result;
    }

    static Character firstUnique(String s) {
        Map<Character, Integer> counts = new LinkedHashMap<>();
        for (char c : s.toCharArray()) counts.merge(c, 1, Integer::sum);
        for (Map.Entry<Character, Integer> e : counts.entrySet()) {
            if (e.getValue() == 1) return e.getKey();
        }
        return null;
    }

    static SortedMap<Integer, List<String>> byLength(List<String> words) {
        SortedMap<Integer, Set<String>> groups = new TreeMap<>();
        for (String w : words) groups.computeIfAbsent(w.length(), k -> new LinkedHashSet<>()).add(w);
        SortedMap<Integer, List<String>> result = new TreeMap<>();
        for (Map.Entry<Integer, Set<String>> e : groups.entrySet()) result.put(e.getKey(), new ArrayList<>(e.getValue()));
        return result;
    }

    static boolean isBalanced(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '(', '[', '{' -> stack.push(c);
                case ')', ']', '}' -> {
                    char open = c == ')' ? '(' : c == ']' ? '[' : '{';
                    if (stack.isEmpty() || stack.pop() != open) return false;
                }
                default -> { }
            }
        }
        return stack.isEmpty();
    }
}

unitTests:
test("top words", () -> {
    checkEq(Text.topWords("The cat and the hat. THE end, and so on", 3), List.of("the", "and", "cat"));
    checkEq(Text.topWords("b a b c a b", 10), List.of("b", "a", "c"));
    checkEq(Text.topWords("", 3), List.of());
});

test("first unique character", () -> {
    checkEq(Text.firstUnique("swiss"), 'w');
    checkEq(Text.firstUnique("aabbcc"), null);
    checkEq(Text.firstUnique("x"), 'x');
});

test("grouping by length", () -> {
    SortedMap<Integer, List<String>> g = Text.byLength(List.of("fig", "pear", "kiwi", "fig", "plum", "banana"));
    checkEq(new ArrayList<>(g.keySet()), List.of(3, 4, 6));
    checkEq(g.get(4), List.of("pear", "kiwi", "plum"));
    checkEq(g.get(3), List.of("fig"));
    checkEq(Text.byLength(List.of()).isEmpty(), true);
});

test("balanced brackets", () -> {
    checkEq(Text.isBalanced("a(b[c]{d}e)f"), true);
    checkEq(Text.isBalanced("([)]"), false);
    checkEq(Text.isBalanced("(("), false);
    checkEq(Text.isBalanced("())"), false);
    checkEq(Text.isBalanced(""), true);
});

